import React from "react";
import axios from "axios";

function App({ keycloak }) {

    console.log("App received keycloak:", keycloak);

    // ✅ HARD GUARD (fixes your crash)
    if (!keycloak || !keycloak.tokenParsed) {
        console.log("⏳ Waiting for Keycloak...");
        return <div>Loading authentication...</div>;
    }

    const callPrivateApi = async () => {
        try {
            await keycloak.updateToken(30);

            const response = await axios.get(
                "http://localhost:7070/api/product",
                {
                    headers: {
                        Authorization: `Bearer ${keycloak.token}`,
                    },
                }
            );

            console.log(response.data);

        } catch (error) {
            console.error("API error:", error);
        }
    };

    return (
        <div style={{ padding: "20px" }}>
            <h2>Keycloak React App</h2>

            <p>
                <strong>User:</strong>{" "}
                {keycloak.tokenParsed?.preferred_username}
            </p>

            <button onClick={callPrivateApi}>
                Call API
            </button>

            <br /><br />

            <button onClick={() => keycloak.logout()}>
                Logout
            </button>
        </div>
    );
}

export default App;

import { Navigate, Route, Routes } from "react-router-dom";
import "./App.css";
import Layout from "./components/Layout";
import CreateProductPage from "./pages/CreateProductPage";
import InventoryCheckPage from "./pages/InventoryCheckPage";
import PlaceOrderPage from "./pages/PlaceOrderPage";
import ProductListPage from "./pages/ProductListPage";

function App({ keycloak }) {
  if (!keycloak || !keycloak.tokenParsed) {
    return <div className="loading">Loading authentication...</div>;
  }

  return (
    <Routes>
      <Route path="/" element={<Layout keycloak={keycloak} />}>
        <Route index element={<Navigate to="/products" replace />} />
        <Route path="products" element={<ProductListPage />} />
        <Route path="products/create" element={<CreateProductPage />} />
        <Route path="orders/create" element={<PlaceOrderPage />} />
        <Route path="inventory/check" element={<InventoryCheckPage />} />
        <Route path="*" element={<Navigate to="/products" replace />} />
      </Route>
    </Routes>
  );
}

export default App;

function ApiResultCard({ title, value }) {
  if (value === null || value === undefined || value === "") {
    return null;
  }

  const textValue = typeof value === "string" ? value : JSON.stringify(value, null, 2);

  return (
    <section className="result-card">
      <h3>{title}</h3>
      <pre>{textValue}</pre>
    </section>
  );
}

export default ApiResultCard;

import { NavLink, Outlet } from "react-router-dom";

const navItems = [
  { to: "/products", label: "Product Catalog" },
  { to: "/products/create", label: "Create Product" },
  { to: "/orders/create", label: "Place Order" },
  { to: "/inventory/check", label: "Check Inventory" },
];

function Layout({ keycloak }) {
  return (
    <div className="app-shell">
      <header className="app-header">
        <div>
          <h1>SKT Ecommerce Console</h1>
          <p className="subtitle">Frontend screens for every backend controller endpoint.</p>
        </div>
        <div className="header-actions">
          <span className="user-pill">{keycloak?.tokenParsed?.preferred_username || "Authenticated user"}</span>
          <button type="button" onClick={() => keycloak.logout()}>
            Logout
          </button>
        </div>
      </header>

      <nav className="main-nav">
        {navItems.map((item) => (
          <NavLink
            key={item.to}
            to={item.to}
            className={({ isActive }) => (isActive ? "nav-link active" : "nav-link")}
          >
            {item.label}
          </NavLink>
        ))}
      </nav>

      <main className="content-area">
        <Outlet context={{ keycloak }} />
      </main>
    </div>
  );
}

export default Layout;

