  });

import { useState } from "react";
import { useOutletContext } from "react-router-dom";
import ApiResultCard from "../components/ApiResultCard";
import { createProduct } from "../services/productApi";

const initialForm = {
  id: "",
  name: "",
  description: "",
  price: "",
};

function CreateProductPage() {
  const { keycloak } = useOutletContext();
  const [form, setForm] = useState(initialForm);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const [result, setResult] = useState(null);

  const handleChange = (event) => {
    const { name, value } = event.target;
    setForm((previous) => ({ ...previous, [name]: value }));
  };

  const handleSubmit = async (event) => {
    event.preventDefault();
    setLoading(true);
    setError("");
    setResult(null);

    try {
      const payload = {
        id: form.id,
        name: form.name,
        description: form.description,
        price: Number(form.price),
      };

      const response = await createProduct(keycloak, payload);
      setResult(response);
      setForm(initialForm);
    } catch (err) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  return (
    <section className="page-card">
      <h2>POST /api/product</h2>
      <p className="status">Create a new product using the same payload fields from ProductRequest.</p>

      <form className="form-grid" onSubmit={handleSubmit}>
        <label>
          Product ID
          <input name="id" value={form.id} onChange={handleChange} required />
        </label>

        <label>
          Name
          <input name="name" value={form.name} onChange={handleChange} required />
        </label>

        <label>
          Description
          <input name="description" value={form.description} onChange={handleChange} required />
        </label>

        <label>
          Price
          <input
            type="number"
            step="0.01"
            min="0"
            name="price"
            value={form.price}
            onChange={handleChange}
            required
          />
        </label>

        <button type="submit" disabled={loading}>
          {loading ? "Creating..." : "Create Product"}
        </button>
      </form>

      {error && <p className="status error">{error}</p>}
      <ApiResultCard title="Created Product" value={result} />
    </section>
  );
}

export default CreateProductPage;

import { useState } from "react";
import { useOutletContext } from "react-router-dom";
import ApiResultCard from "../components/ApiResultCard";
import { checkInventory } from "../services/inventoryApi";

function InventoryCheckPage() {
  const { keycloak } = useOutletContext();
  const [skuCode, setSkuCode] = useState("");
  const [quantity, setQuantity] = useState(1);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const [result, setResult] = useState(null);

  const handleSubmit = async (event) => {
    event.preventDefault();
    setLoading(true);
    setError("");
    setResult(null);

    try {
      const response = await checkInventory(keycloak, skuCode, Number(quantity));
      setResult({ skuCode, quantity: Number(quantity), inStock: Boolean(response) });
    } catch (err) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  return (
    <section className="page-card">
      <h2>GET /api/inventory</h2>
      <p className="status">Check if a quantity is currently in stock.</p>

      <form className="form-grid" onSubmit={handleSubmit}>
        <label>
          SKU Code
          <input value={skuCode} onChange={(event) => setSkuCode(event.target.value)} required />
        </label>

        <label>
          Quantity
          <input
            type="number"
            min="1"
            value={quantity}
            onChange={(event) => setQuantity(event.target.value)}
            required
          />
        </label>

        <button type="submit" disabled={loading}>
          {loading ? "Checking..." : "Check Inventory"}
        </button>
      </form>

      {error && <p className="status error">{error}</p>}
      <ApiResultCard title="Inventory Result" value={result} />
    </section>
  );
}

export default InventoryCheckPage;

import { useState } from "react";
import { useOutletContext } from "react-router-dom";
import ApiResultCard from "../components/ApiResultCard";
import { placeOrder } from "../services/orderApi";

const initialForm = {
  id: "",
  orderNumber: "",
  skuCode: "",
  price: "",
  quantity: "",
};

function PlaceOrderPage() {
  const { keycloak } = useOutletContext();
  const [form, setForm] = useState(initialForm);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const [result, setResult] = useState("");

  const handleChange = (event) => {
    const { name, value } = event.target;
    setForm((previous) => ({ ...previous, [name]: value }));
  };

  const handleSubmit = async (event) => {
    event.preventDefault();
    setLoading(true);
    setError("");
    setResult("");

    try {
      const payload = {
        id: Number(form.id),
        orderNumber: form.orderNumber,
        skuCode: form.skuCode,
        price: Number(form.price),
        quantity: Number(form.quantity),
      };

      const response = await placeOrder(keycloak, payload);
      setResult(response);
      setForm(initialForm);
    } catch (err) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  return (
    <section className="page-card">
      <h2>POST /api/order</h2>
      <p className="status">Place an order with the fields from OrderRequest.</p>

      <form className="form-grid" onSubmit={handleSubmit}>
        <label>
          ID
          <input type="number" min="1" name="id" value={form.id} onChange={handleChange} required />
        </label>

        <label>
          Order Number
          <input name="orderNumber" value={form.orderNumber} onChange={handleChange} required />
        </label>

        <label>
          SKU Code
          <input name="skuCode" value={form.skuCode} onChange={handleChange} required />
        </label>

        <label>
          Price
          <input
            type="number"
            min="0"
            step="0.01"
            name="price"
            value={form.price}
            onChange={handleChange}
            required
          />
        </label>

        <label>
          Quantity
          <input type="number" min="1" name="quantity" value={form.quantity} onChange={handleChange} required />
        </label>

        <button type="submit" disabled={loading}>
          {loading ? "Placing..." : "Place Order"}
        </button>
      </form>

      {error && <p className="status error">{error}</p>}
      <ApiResultCard title="Order API Response" value={result} />
    </section>
  );
}

export default PlaceOrderPage;

import { useEffect, useState } from "react";
import { useOutletContext } from "react-router-dom";
import { getAllProducts } from "../services/productApi";

function ProductListPage() {
  const { keycloak } = useOutletContext();
  const [products, setProducts] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  const loadProducts = async () => {
    setLoading(true);
    setError("");

    try {
      const data = await getAllProducts(keycloak);
      setProducts(Array.isArray(data) ? data : []);
    } catch (err) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadProducts();
  }, []);

  return (
    <section className="page-card">
      <div className="page-title-row">
        <h2>GET /api/product</h2>
        <button type="button" onClick={loadProducts} disabled={loading}>
          {loading ? "Loading..." : "Refresh"}
        </button>
      </div>

      {error && <p className="status error">{error}</p>}
      {!error && products.length === 0 && !loading && <p className="status">No products found yet.</p>}

      {products.length > 0 && (
        <div className="table-wrap">
          <table>
            <thead>
              <tr>
                <th>ID</th>
                <th>Name</th>
                <th>Description</th>
                <th>Price</th>
              </tr>
            </thead>
            <tbody>
              {products.map((product) => (
                <tr key={product.id}>
                  <td>{product.id}</td>
                  <td>{product.name}</td>
                  <td>{product.description}</td>
                  <td>{product.price}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </section>
  );
}

export default ProductListPage;

import axios from "axios";

const apiClient = axios.create({
  baseURL: "http://localhost:7070",
  timeout: 10000,
});

export async function getBearerToken(keycloak) {
  if (!keycloak) {
    throw new Error("Authentication is not ready yet.");
  }

  await keycloak.updateToken(30);
  return keycloak.token;
}

apiClient.interceptors.response.use(
  (response) => response,
  (error) => {
    const fallbackMessage = "Request failed. Please try again.";
    const serverMessage = error?.response?.data;

    if (typeof serverMessage === "string" && serverMessage.trim().length > 0) {
      return Promise.reject(new Error(serverMessage));
    }

    return Promise.reject(new Error(error.message || fallbackMessage));
  }
);

export default apiClient;

import apiClient, { getBearerToken } from "./apiClient";

export async function checkInventory(keycloak, skuCode, quantity) {
  const token = await getBearerToken(keycloak);
  const response = await apiClient.get("/api/inventory", {
    headers: {
      Authorization: `Bearer ${token}`,
    },
    params: {
      skuCode,
      quantity,
    },
  });

  return response.data;
}

import apiClient, { getBearerToken } from "./apiClient";

export async function placeOrder(keycloak, payload) {
  const token = await getBearerToken(keycloak);
  const response = await apiClient.post("/api/order", payload, {
    headers: {
      Authorization: `Bearer ${token}`,
      "Content-Type": "application/json",
    },
  });

  return response.data;
}

import apiClient, { getBearerToken } from "./apiClient";

export async function getAllProducts(keycloak) {
  const token = await getBearerToken(keycloak);
  const response = await apiClient.get("/api/product", {
    headers: {
      Authorization: `Bearer ${token}`,
    },
  });

  return response.data;
}

export async function createProduct(keycloak, payload) {
  const token = await getBearerToken(keycloak);
  const response = await apiClient.post("/api/product", payload, {
    headers: {
      Authorization: `Bearer ${token}`,
      "Content-Type": "application/json",
    },
  });

  return response.data;
}
